// ============================================
// VocabularyData Wrapper
// Provides getWords() and getGrammarRules()
// ============================================

const CATEGORY_MAP = {
  'greetings': 'التحيات',
  'numbers': 'الأرقام',
  'food': 'الطعام',
  'family': 'العائلة',
  'travel': 'السفر',
  'work': 'العمل',
  'weather': 'الطقس',
  'shopping': 'التسوق'
};

const VocabularyData = {
  getWords: function(level, category) {
    if (typeof DATA === 'undefined' || !DATA[level]) return [];
    var cats = DATA[level].categories;
    if (!cats) return [];
    var allWords = [];
    var catNames = Object.keys(cats);
    catNames.forEach(function(catName) {
      var shouldInclude = false;
      if (!category || category === 'all') {
        shouldInclude = true;
      } else {
        var mappedName = CATEGORY_MAP[category] || category;
        if (catName.indexOf(mappedName) >= 0) shouldInclude = true;
      }
      if (shouldInclude) {
        cats[catName].forEach(function(w) {
          allWords.push({
            de: w.de,
            ar: w.ar,
            article: w.article || 'none',
            pronunciation: w.phonetic || '',
            example: w.example || '',
            exampleAr: w.ex_ar || '',
            level: level,
            category: catName
          });
        });
      }
    });
    return allWords;
  },

  getGrammarRules: function(category) {
    if (typeof GRAMMAR === 'undefined') return [];
    var levels = ['A1', 'A2', 'B1', 'B2', 'C1', 'C2'];
    var allRules = [];
    levels.forEach(function(level) {
      var rules = GRAMMAR[level];
      if (!rules || !Array.isArray(rules)) return;
      rules.forEach(function(rule) {
        var ruleData = {
          title: rule.title,
          level: level,
          explanation: rule.explanation || '',
          examples: [],
          category: 'all'
        };
        // Detect category from title
        var title = rule.title.toLowerCase();
        if (title.indexOf('ضمائر') >= 0 || title.indexOf('pronomen') >= 0) ruleData.category = 'nouns';
        else if (title.indexOf('أداة') >= 0 || title.indexOf('artikel') >= 0) ruleData.category = 'articles';
        else if (title.indexOf('فعل') >= 0 || title.indexOf('verben') >= 0) ruleData.category = 'verbs';
        else if (title.indexOf('صفة') >= 0 || title.indexOf('adjektiv') >= 0) ruleData.category = 'adjectives';
        else if (title.indexOf('جر') >= 0 || title.indexOf('präposition') >= 0) ruleData.category = 'prepositions';
        else if (title.indexOf('جمل') >= 0 || title.indexOf('satz') >= 0) ruleData.category = 'sentence';
        else if (title.indexOf('حالة') >= 0 || title.indexOf('kasus') >= 0) ruleData.category = 'cases';
        else if (title.indexOf('تصريف') >= 0 || title.indexOf('konjugation') >= 0) ruleData.category = 'verbs';
        else if (title.indexOf('جمع') >= 0 || title.indexOf('plural') >= 0) ruleData.category = 'nouns';
        else if (title.indexOf('als') >= 0 || title.indexOf('kein') >= 0 || title.indexOf(' Possessiv') >= 0) ruleData.category = 'articles';
        else if (title.indexOf('zahlen') >= 0 || title.indexOf('komma') >= 0) ruleData.category = 'nouns';

        if (rule.examples) {
          rule.examples.forEach(function(ex) {
            ruleData.examples.push({ de: ex.de, ar: ex.ar });
          });
        }
        allRules.push(ruleData);
      });
    });

    if (!category || category === 'all') return allRules;
    return allRules.filter(function(r) { return r.category === category; });
  },

  getAllWords: function(level) {
    return this.getWords(level, 'all');
  },

  getWordCount: function(level) {
    return this.getWords(level, 'all').length;
  },

  getReviewWords: function(level) {
    if (typeof Progress === 'undefined') return [];
    var words = this.getWords(level, 'all');
    var learning = Progress.getMyWords('learning');
    var learningDe = learning.map(function(w) { return w.de; });
    return words.filter(function(w) { return learningDe.indexOf(w.de) >= 0; });
  }
};
